await Store.EnqueueAsync(
    SendEmailAction.Key,
    new EmailInput
    {
        To = "test@test.com"
    });

public sealed class EmailInput
{
    public string? To { get; set; }
}

public sealed class SendEmailAction : JobAction<EmailInput>
{
    private readonly SmtpSettings? _smtp;

    public SendEmailAction(SmtpSettings? smtp)
    {
        _smtp = smtp;
    }

    public override Task<ActionResult> ExecuteAsync(
        EmailInput input,
        CancellationToken ct)
    {
        var host = _smtp?.Host ?? "<not configured>";
        var to = input.To ?? "<no recipient>";

        ReportProgress(100, $"SMTP: {host}, To: {to}");

        return Task.FromResult(
            ActionResults.Next(
                JobCommands.Next<LogAction>(
                    new LogInput
                    {
                        Message = $"Email sent to {to}"
                    })));
    }
}

public sealed class LogInput
{
    public string? Message { get; set; }
}

// Executed automatically after SendEmailAction
